Implicit use of pointers
class Superclass {
    public void display() {
        System.out.println("Superclass");
    }
}
class Subclass extends Superclass {
    @Override
    public void display() {
        System.out.println("Subclass");
    }
}
public class Main {
    public static void main(String[] args) {
        Superclass obj = new Subclass(); 
        obj.display(); // Output: ???
    }
}
